class Task {
int id;
String title;
DateTime date;
String priority;
int status; // 0 - Incomplete, 1 - Complete

Task({this.title, this.date, this.priority, this.status});

Task.withId({this.id, this.title, this.date, this.priority, this.status});

Map<String, dynamic> toMap() {
final map = Map<String, dynamic>();
if (id != null) {
map['id'] = id;
}
map['title'] = title;
map['date'] = date.toIso8601String();
map['priority'] = priority;
map['status'] = status;
return map;
}

factory Task.fromMap(Map<String, dynamic> map) {
return Task.withId(
id: map['id'],
title: map['title'],
date: DateTime.parse(map['date']),
priority: map['priority'],
status: map['status'],
);
}
}

static final DatabaseHelper instance = DatabaseHelper.-instance();
static Database -db;

DatabaseHelper.-instance();

String tasksTable = 'task-table';
String colId = 'id';
String colTitle = 'title';
String colDate = 'date';
String colPriority = 'priority';
String colStatus = 'status';

Future<Database> get db async {
if (-db == null) {
-db = await -initDb();
}
return -db;
}

Future<Database> -initDb() async {
Directory dir = await getApplicationDocumentsDirectory();
String path = dir.path + '/todo-list.db';
final todoListDb =
await openDatabase(path, version: 1, onCreate: -createDb);
return todoListDb;
}

void -createDb(Database db, int version) async {
await db.execute(
'CREATE TABLE $tasksTable($colId INTEGER PRIMARY KEY AUTOINCREMENT, $colTitle TEXT, $colDate TEXT, $colPriority TEXT, $colStatus INTEGER)',
);
}

Future<List<Map<String, dynamic>>> getTaskMapList() async {
Database db = await this.db;
final List<Map<String, dynamic>> result = await db.query(tasksTable);
return result;
}

Future<List<Task>> getTaskList() async {
final List<Map<String, dynamic>> taskMapList = await getTaskMapList();
final List<Task> taskList = [];
taskMapList.forEach((taskMap) {
taskList.add(Task.fromMap(taskMap));
});
taskList.sort((taskA, taskB) => taskA.date.compareTo(taskB.date));
return taskList;
}

Future<int> insertTask(Task task) async {
Database db = await this.db;
final int result = await db.insert(tasksTable, task.toMap());
return result;
}

Future<int> updateTask(Task task) async {
Database db = await this.db;
final int result = await db.update(
tasksTable,
task.toMap(),
where: '$colId = ?',
whereArgs: [task.id],
);
return result;
}

Future<int> deleteTask(int id) async {
Database db = await this.db;
final int result = await db.delete(
tasksTable,
where: '$colId = ?',
whereArgs: [id],
);
return result;
}

Future<int> deleteAllTask() async {
Database db = await this.db;
final int result = await db.delete(tasksTable);
return result;
}

