void onData(Position position) { 
if(position == null) { 
return; 
} 
double dir = distanceBetween(-lastLat, -lastLong, position.latitude, position.longitude); 

if(dir > 10) { 
-lastLat = position.latitude; 
-lastLong = position.longitude; 

String timestamp = getTimestamp(); 
update(0, position.latitude, timestamp: timestamp); 
update(1, position.longitude, timestamp: timestamp); 
} 

text = "${position.latitude}, ${position.longitude}"; 
call(); 
} 

