class RunScreen extends StatefulWidget { 
static const routeName = '/run'; 
final String networkID; 

const RunScreen({ this.networkID }); 

@override 
-RunScreenState createState() => -RunScreenState(); 
}

class -RunScreenState extends State<RunScreen> { 
Manager -manager; 
Value -cameraValue; 
List<Widget> -children; 
String -status = "Please wait..."; 
CountDownController -controller = CountDownController(); 
int -duration = 10; 
int -values = 0; 
String -name = ""; 
double -progress = 0.5; 
int -send = 0; 
int -total = 0; 
bool -showProgress = false; 

@override 
void initState() { 
super.initState(); 

-manager = Manager(state: this, networkID: widget.networkID); 
setup(); 
} 

@override 
void dispose() { 
-manager.stop(); 
super.dispose(); 
} 

void updateStatus(msg) { 
setState(() => -status = msg); 
} 

Future<void> setup() async { 
if(await -manager.setup()) { 
updateStatus("Run for ${widget.networkID}"); 
-duration = 10; 
-manager.configurations.forEach((c) { 
if(c.name == 'Run Time') { 
if(c.value[0] != null) { 
-duration = int.parse(c.value[0].states[0].data); 
} 
} else if(c.name == 'Picture') { 
-cameraValue = c.value[0]; 
} 
}); 
-manager.sensors.forEach((sen) { 
sen.value.forEach((val) { 
if(val != null) { 
-values++; 
} 
}); 
}); 
-name = -manager.network.name; 
setState(() { 
-children = List<Widget>(); 
-children.add(getStartInfo()); 
-children.add(getStartButton()); 
if(-cameraValue != null) { 
-children.add(getTakePicture()); 
} 
}); 
} else { 
updateStatus("Failed to load '${widget.networkID}' because '${-manager.error}'"); 
} 
} 

@override 
Widget build(BuildContext context) { 
List<Widget> children = List<Widget>(); 

if(-children != null) { 
children.addAll(-children); 
} else { 
children.add( 
Text( 
-status, 
textAlign: TextAlign.center, 
style: TextStyle(fontWeight: FontWeight.bold), 
) 
); 
} 

if(-showProgress) { 
children.add(getProgress()); 
} 

return Scaffold( 
appBar: AppBar( 
title: Text('Run measurement'), 
leading: new IconButton( 
icon: new Icon(Icons.arrow-back), 
onPressed: -done, 
), 
), 
body: Center( 
child: Column( 
mainAxisAlignment: MainAxisAlignment.spaceEvenly, 
children: children 
), 
), 
); 
} 

