-updateTimersTimer = Timer.periodic(const Duration(seconds: 1), 
(-) => BlocProvider.of<TimersBloc>(context).add(const UpdateNow())); 
super.initState(); 
WidgetsBinding.instance.addObserver(this); 
brightness = WidgetsBinding.instance.platformDispatcher.platformBrightness; 

