tooltipBgColor: theme.cardColor, 
getTooltipItems: (List<LineBarSpot> spots) { 
return spots.map((LineBarSpot spot) { 
return LineTooltipItem( 
L10N 
.of(context) 
.tr 
.nHours(spot.y.toStringAsFixed(1)), 
theme.textTheme.bodyMedium!.copyWith( 
color: spot.bar.color, 
)); 
}).toList(); 
})), 
titlesData: FlTitlesData( 
show: true, 
leftTitles: AxisTitles( 
sideTitles: SideTitles( 
showTitles: true, 
getTitlesWidget: (double v, -) => Text( 
v.toStringAsFixed(1), 
style: theme.textTheme.bodySmall, 
), 
interval: 5.0, 
)), 
bottomTitles: AxisTitles( 
sideTitles: SideTitles( 
reservedSize: 35, 
showTitles: true, 
getTitlesWidget: (double dweek, -) { 
int week = dweek.toInt(); 
DateTime date = 
firstDate!.add(Duration(days: week * 7)); 
return Container( 
