on<AllAlbumsImageCheckedChanged>(-onCheckedImageChanged); 
on<AllAlbumsImageClearChecked>(-onImageClearChecked); 
on<AllAlbumsClearDeletedImage>(-onClearDeletedImage); 
on<AllAlbumsDeleteSubmitted>(-onDeleteSubmitted); 
on<AllAlbumsCopySubmitted>(-onCopyAlbumsSubmitted); 
on<AllAlbumsCancelCopySubmitted>(-onCancelCopySubmitted); 
on<AllAlbumsCopyStatusChanged>(-onCopyAlbumsStatusChanged); 
on<AllAlbumsDeleteImagesSubmitted>(-onDeleteImagesSubmitted); 
on<AllAlbumsCopyImagesSubmitted>(-onCopyImagesSubmitted); 
on<AllAlbumsUploadPhotos>(-onUploadPhotos); 
