on<SubscriptionRequested>(-onSubscriptionRequest); 
on<SelectedAccountChanged>(-onSelectedAccountChanged); 
on<SelectedGroupChanged>(-onSelectedGroupChanged); 
on<ContactFieldItemColumnOperation>(-onFieldItemColumnOperate); 
on<ContactDataTypeChanged>(-onContactDataTypeChanged); 
on<AddCustomDataType>(-onAddCustomDataType); 
on<NameValueChanged>(-onNameValueChanged); 
