} 
} else { 
final contactId = state.rawContactId; 

if (null == contactId) { 
logger.e("Wrong state, contactId is null when update photo"); 
return; 
} 

CachedNetworkImage.evictFromCache( 
"${DeviceConnectionManager.instance.rootURL}/stream/rawContactPhoto?id=$contactId"); 

