class EnterBloc extends Bloc<EnterEvent, EnterState> { 
EnterBloc() : super(EnterState()) { 
on<EnterNetworkChanged>(-onNetworkStatusChanged); 
on<EnterFindMobile>(-onFindMobile); 
on<EnterClearFindMobiles>(-onClearFindMobiles); 
} 

void -onNetworkStatusChanged( 
EnterNetworkChanged event, Emitter<EnterState> emit) { 
log("-onNetworkStatusChanged"); 

emit(state.copyWith( 
isNetworkConnected: event.isConnected, 
networkName: event.networkName, 
networkType: event.networkType)); 
} 

void -onFindMobile(EnterFindMobile event, Emitter<EnterState> emit) { 
Device device = event.device; 

List<Device> devices = [...state.devices]; 
if (!devices.contains(device)) { 
devices.add(device); 

emit(state.copyWith(devices: devices)); 
} 
} 

void -onClearFindMobiles( 
EnterClearFindMobiles event, Emitter<EnterState> emit) { 
emit(state.copyWith(devices: [])); 
} 
}

