abstract class EnterEvent extends Equatable { 
const EnterEvent(); 

@override 
List<Object?> get props => []; 
}

class EnterNetworkChanged extends EnterEvent { 
final bool isConnected; 
final String? networkName; 
final NetworkType networkType; 

const EnterNetworkChanged(this.isConnected, this.networkName, this.networkType); 

@override 
List<Object?> get props => [isConnected, networkName, networkType]; 
}

class EnterFindMobile extends EnterEvent { 
final Device device; 

const EnterFindMobile(this.device); 

@override 
List<Object?> get props => [device]; 
}

class EnterClearFindMobiles extends EnterEvent { 
const EnterClearFindMobiles(); 
}

class EnterState extends Equatable { 
final bool isNetworkConnected; 
final String? networkName; 
final List<Device> devices; 
final NetworkType networkType; 

const EnterState({ 
this.isNetworkConnected = true, 
this.networkName = null, 
this.devices = const [], 
this.networkType = NetworkType.wifi 
}); 

@override 
List<Object?> get props => [isNetworkConnected, networkName, devices, networkType]; 

EnterState copyWith({ 
bool? isNetworkConnected, 
String? networkName, 
List<Device>? devices, 
NetworkType? networkType 
}) { 
return EnterState( 
isNetworkConnected: isNetworkConnected ?? this.isNetworkConnected, 
networkName: networkName ?? this.networkName, 
devices: devices ?? this.devices, 
networkType: networkType ?? this.networkType 
); 
} 
}

