class -EnterState extends State<EnterPage> 
with SingleTickerProviderStateMixin 
implements HeartbeatListener { 
static final -ICON-SIZE = 80.0; 

AnimationController? -animationController; 

// 记录上一次设备显示坐标位置（Key为设备IP） 
Map<String, Rect> -deviceRectMap = Map(); 

NeatPeriodicTaskScheduler? -refreshDeviceScheduler; 

HeartbeatClient? -heartbeatClient = null; 
CmdClient? -cmdClient = null; 

StreamSubscription<ConnectivityResult>? -networkConnectivitySubscription = 
null; 
StreamSubscription<ExitHeartbeatService>? -exitHeartbeatServiceStream; 
StreamSubscription<ExitCmdService>? -exitCmdServiceStream; 

@override 
void initState() { 
super.initState(); 

-registerEventBus(); 

-networkConnectivitySubscription = Connectivity() 
.onConnectivityChanged 
.listen((ConnectivityResult result) async { 
log("-isNetworkConnected: ${-isNetworkConnected(result)}"); 
NetworkType networkType = result == ConnectivityResult.wifi 
? NetworkType.wifi 
: NetworkType.ethernet; 
if (-isNetworkConnected(result)) { 
final info = NetworkInfo(); 
String? networkName = ""; 

try { 
networkName = await info.getWifiName(); 
} catch (e) { 
log("info.getWifiName() throw error: $e"); 
} 
context 
.read<EnterBloc>() 
.add(EnterNetworkChanged(true, networkName, networkType)); 

-startSearchDevices(); 

-startRefreshDeviceScheduler(); 
} else { 
context 
.read<EnterBloc>() 
.add(EnterNetworkChanged(false, null, networkType)); 
} 
}); 

Connectivity().checkConnectivity().then((result) async { 
log("Initial network check: ${-isNetworkConnected(result)}"); 
NetworkType networkType = result == ConnectivityResult.wifi 
? NetworkType.wifi 
: NetworkType.ethernet; 

if (-isNetworkConnected(result)) { 
final info = NetworkInfo(); 
String? networkName = ""; 

try { 
networkName = await info.getWifiName(); 
} catch (e) { 
log("info.getWifiName() throw error: $e"); 
} 

context 
.read<EnterBloc>() 
.add(EnterNetworkChanged(true, networkName, networkType)); 
} else { 
context 
.read<EnterBloc>() 
.add(EnterNetworkChanged(false, null, networkType)); 
} 
}).catchError((error) { 
log("Initial network check error: $error"); 
}); 
} 

