class HomeBloc extends Bloc<HomeEvent, HomeState> { 
final CommonRepository -commonRepository; 
final UpdateChecker -updateChecker = UpdateChecker.create(); 
final StreamController<HomeLinearProgressIndicatorStatus> 
-progressIndicatorStreamController = StreamController(); 
final StreamController<UpdateDownloadStatusUnit> 
-updateDownloadStatusController = StreamController(); 
final StreamController<MobileInfo> -updateMobileInfoStreamController = 
StreamController(); 

Stream<HomeLinearProgressIndicatorStatus> get progressIndicatorStream => 
-progressIndicatorStreamController.stream; 
Stream<UpdateDownloadStatusUnit> get updateDownloadStatusStream => 
-updateDownloadStatusController.stream; 
Stream<MobileInfo> get updateMobileInfoStream => 
-updateMobileInfoStreamController.stream; 

HomeBloc({required CommonRepository commonRepository}) 
: -commonRepository = commonRepository, 
super(HomeState(tab: HomeTab.image)) { 
on<HomeTabChanged>(-onHomeTabChanged); 
on<HomeSubscriptionRequested>(-onSubscriptionRequested); 
on<HomeCheckUpdateRequested>(-onCheckUpdateRequested); 
on<HomeNewVersionAvailable>(-onNewVersionAvailable); 
on<HomeProgressIndicatorStatusChanged>(-onProgressIndicatorStatusChanged); 
on<HomeUpdateDownloadStatusChanged>(-onUpdateDownloadStatusChanged); 
on<HomeCheckUpdateStatusChanged>(-onUpdateCheckStatusChanged); 
on<HomeUpdateMobileInfo>(-onUpdateMobileInfo); 
} 

void -onHomeTabChanged(HomeTabChanged event, Emitter<HomeState> emit) { 
emit(state.copyWith(tab: event.tab)); 
} 

void -onSubscriptionRequested( 
HomeSubscriptionRequested event, Emitter<HomeState> emit) async { 
try { 
MobileInfo mobileInfo = await -commonRepository.getMobileInfo(); 

-updateMobileInfoStreamController.add(mobileInfo); 
} catch (e) { 
logger.e("-onSubscriptionRequested: ${e.toString()}"); 
} 
} 

void -onCheckUpdateRequested( 
HomeCheckUpdateRequested event, Emitter<HomeState> emit) async { 
if (kIsWeb) return; 

if (Platform.isLinux) { 
add(HomeCheckUpdateStatusChanged(UpdateCheckStatusUnit( 
status: UpdateCheckStatus.start, isAutoCheck: event.isAutoCheck))); 

-updateChecker.onCheckFailure((error) { 
if (isClosed) return; 

add(HomeCheckUpdateStatusChanged(UpdateCheckStatusUnit( 
status: UpdateCheckStatus.failure, 
isAutoCheck: event.isAutoCheck, 
failureReason: "${error.toString()}"))); 
}); 

-updateChecker.onNoUpdateAvailable(() { 
if (isClosed) return; 

add(HomeCheckUpdateStatusChanged(UpdateCheckStatusUnit( 
status: UpdateCheckStatus.success, 
isAutoCheck: event.isAutoCheck, 
hasUpdateAvailable: false))); 
}); 

-updateChecker 
.onUpdateAvailable((publishTime, version, assets, updateInfo) { 
if (isClosed) return; 

add(HomeNewVersionAvailable( 
publishTime, version, assets, updateInfo, event.isAutoCheck)); 
}); 

-updateChecker.check(); 
