void -setImageScale( 
BuildContext context, double currentScale, bool isEnlarge) { 
if (isEnlarge) { 
double targetScale = 1.5; 
for (int i = 0; i <= Constant.IMAGE-MAX-SCALE ~/ 0.5; i++) { 
double value = Constant.IMAGE-MAX-SCALE - 0.5 * i; 

if (value - currentScale <= 0.5) { 
targetScale = value; 

if (targetScale < 1.5) targetScale = 1.5; 

break; 
} 
} 
context.read<ImageDetailBloc>().add(ImageDetailScaleChanged(targetScale)); 
} else { 
double targetScale = 1.0; 
for (int i = 0; i <= Constant.IMAGE-MAX-SCALE ~/ 0.5; i++) { 
double value = i * 0.5 + 1.0; 
if (currentScale - value <= 0.5) { 
targetScale = value; 
break; 
} 
} 
context.read<ImageDetailBloc>().add(ImageDetailScaleChanged(targetScale)); 
} 
} 

void -openPreImage(int currentIndex, List<ImageItem> images) { 
if (currentIndex > 0 && currentIndex < images.length) { 
-extendedPageController?.jumpToPage(currentIndex - 1); 
} 
} 

void -openNextImage(int currentIndex, List<ImageItem> images) { 
if (currentIndex < images.length - 1 && currentIndex + 1 >= 0) { 
-extendedPageController?.jumpToPage(currentIndex + 1); 
} 
} 

