return DateTime.now().millisecondsSinceEpoch; 
}

void -sendToServer(Heartbeat heartbeat) async { 
if (-isQuit) { 
-log("Heartbeat: -sendToServer, heartbeat service had quit."); 
return; 
} 

String heartbeatStr = jsonEncode(heartbeat); 
-log("Heartbeat => -sendToServer, $heartbeatStr, socket: $-socket"); 

-socket?.write(heartbeatStr); 
-socket?.flush(); 
}

void -log(String msg) { 
if (Constant.ENABLE-HEARTBEAT-LOG) { 
logger.d("HeartBeat: $msg"); 
} 
}

void -disconnectToServer() async { 
if (-isConnected) { 
await -socketSubscription?.cancel(); 
await -socket?.close(); 
-socket = null; 
-isConnected = false; 

listeners.forEach((listener) { 
listener.onDisconnected(); 
}); 
listeners.clear(); 
} 
}

Future<void> quit() async { 
-isQuit = true; 

-disconnectToServer(); 

-stopTimeoutTimer(); 
-stopDelayTimer(); 
}

@override 
void addListener(HeartbeatListener listener) { 
listeners.add(listener); 
}

void -recycle() { 
-socketSubscription?.cancel(); 
-socket = null; 
-stopTimeoutTimer(); 
-stopDelayTimer(); 
}

