void copyFileTo( 
{required List<String> paths, 
required String dir, 
Function(String fileName)? onDone, 
Function(String fileName, int current, int total)? onProgress, 
Function(String error)? onError, 
String? fileName = null}) async { 
String name = ""; 

if (fileName == null) { 
if (paths.length <= 1) { 
int index = paths.single.lastIndexOf("/"); 

if (index != -1) { 
name = paths.single.substring(index + 1); 
} 
} else { 
final df = DateFormat("yyyyMd-HHmmss"); 

String formatTime = df.format(new DateTime.fromMillisecondsSinceEpoch( 
DateTime.now().millisecondsSinceEpoch)); 

name = "AirController-${formatTime}.zip"; 
} 
} else { 
name = fileName; 
} 

var options = DownloaderUtils( 
progress: ProgressImplementation(), 
file: File("$dir/$name"), 
onDone: () { 
onDone?.call(name); 
}, 
progressCallback: (current, total) { 
onProgress?.call(name, current, total); 
}); 

String pathsStr = Uri.encodeComponent(jsonEncode(paths)); 

String api = "${-domain}/stream/download?paths=$pathsStr"; 

try { 
if (null == -downloaderCore) { 
-downloaderCore = await Flowder.download(api, options); 
} else { 
-downloaderCore?.download(api, options); 
} 
} catch (e) { 
onError?.call(e.toString()); 
} 
}

void cancelDownload() { 
-downloaderCore?.cancel(); 
}

