class CountDownTimer { 
final int millisInFuture; 
final int countDownInterval; 

bool -isCancelled = false; 
Timer? -internalTimer; 
int -currentTime = 0; 

Function(int millisUntilFinished)? -onTick; 
Function()? -onFinish; 

CountDownTimer(this.millisInFuture, this.countDownInterval); 

void start() { 
final duration = Duration(milliseconds: countDownInterval); 
-internalTimer = Timer.periodic(duration, (timer) { 
-currentTime += countDownInterval; 

if (-currentTime >= millisInFuture) { 
-onFinish?.call(); 

-internalTimer?.cancel(); 
} else { 
-onTick?.call(millisInFuture - -currentTime); 
} 
}); 
-isCancelled = false; 
} 

void onTick(Function(int millisUntilFinished) callback) { 
-onTick = callback; 
} 

void onFinish(Function() callback) { 
-onFinish = callback; 
} 

void cancel() { 
-internalTimer?.cancel(); 
-isCancelled = true; 
} 

bool isCancelled() { 
return -isCancelled; 
} 
}

