class StackQueue<T> { 
final -stack = Queue<T>(); 

void push(T element) { 
-stack.addLast(element); 
} 

T pop() { 
final T lastElement = -stack.last; 
-stack.removeLast(); 
return lastElement; 
} 

T? takeLast() { 
List<T> list = -stack.toList(); 
if (list.length > 1) { 
return list[list.length - 2]; 
} 

return null; 
} 

/** 
* 回退到指定的栈数据 
* 
* @param data 栈数据目标 
*/ 
bool popTo(T data) { 
while (-stack.isNotEmpty) { 
T current = -stack.last; 
if (current == data) return true; 

-stack.removeLast(); 
} 

return false; 
} 

bool contains(T data) => -stack.contains(data); 

int get length => -stack.length; 

List<T> toList() { 
return -stack.toList(); 
} 

void clear() { 
-stack.clear(); 
} 

bool get isEmpty => -stack.isEmpty; 

