class SimpleGestureDetector extends StatelessWidget { 
final Widget? child; 
final Function()? onTap; 
final Function()? onDoubleTap; 
final Function(TapDownDetails details)? onTapDown; 
final Function(TapUpDetails tapUpDetails)? onTapUp; 
final Function()? onTapCancel; 
final int doubleTapDuration; 
CountDownTimer? -countDownTimer; 
int -tapCount = 0; 
bool -isCountDownStarted = false; 
int -lastTapTime = -1; 

SimpleGestureDetector({ 
Key? key, 
this.child, 
this.onTap, 
this.onDoubleTap, 
this.onTapDown, 
this.onTapCancel, 
this.onTapUp, 
this.doubleTapDuration = 200 
}) : super(key: key); 

@override 
Widget build(BuildContext context) { 
return GestureDetector( 
child: child, 
onTap: () { 
-tapCount ++; 

Future.delayed(Duration.zero); 

if (-tapCount == 1) { 
-lastTapTime = -currentTimeInMills(); 

if (!-isCountDownStarted) { 
-startCountDownTimer(); 
} 
} 

onTap?.call(); 

if (-tapCount >= 2) { 
int currentTime = -currentTimeInMills(); 
if (currentTime - -lastTapTime <= doubleTapDuration) { 
onDoubleTap?.call(); 
} 
} 
}, 
onTapUp: (details) { 
onTapUp?.call(details); 
}, 
onTapCancel: () { 
onTapCancel?.call(); 
}, 
onTapDown: (details) { 
onTapDown?.call(details); 
}, 
); 
} 

int -currentTimeInMills() { 
return DateTime.now().millisecondsSinceEpoch; 
} 

void -startCountDownTimer() { 
-countDownTimer = CountDownTimer(doubleTapDuration, doubleTapDuration ~/ 10); 
-countDownTimer?.onFinish(() { 
-countDownTimer = null; 
-isCountDownStarted = false; 
-tapCount = 0; 
-lastTapTime = -1; 
}); 

-countDownTimer?.start(); 

-isCountDownStarted = true; 
} 
}

@override 
Widget build(BuildContext context) { 
return GestureDetector( 
child: child, 
onTap: () { 
-tapCount ++; 

Future.delayed(Duration.zero); 

if (-tapCount == 1) { 
