-paint.strokeWidth = dividerWidth; 

canvas.drawLine(Offset(0, 0), Offset(0.5 * x, y), -paint); 
canvas.drawLine(Offset(0.5 * x, y), Offset(x, 0), -paint); 
} 
} 

